{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a mapping")

    payload = case.get("payload", case)
    if not isinstance(payload, dict):
        raise ValueError("payload must be a mapping")

    required_payload_fields = ("nodes", "required_symbols")
    for field in required_payload_fields:
        if field not in payload:
            raise ValueError("missing payload field: " + field)

    nodes = payload["nodes"]
    required_symbols = payload["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a nonempty list")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be a list")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required_symbols must contain strings")

    required = set(required_symbols)
    by_id = {}
    required_node_fields = ("id", "parent", "symbol", "depth", "removable", "utility")
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be a mapping")
        for field in required_node_fields:
            if field not in node:
                raise ValueError("missing node field: " + field)
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        utility = node["utility"]
        if not isinstance(node_id, str) or not node_id:
            raise ValueError("node id must be a nonempty string")
        if node_id in by_id:
            raise ValueError("node ids must be unique")
        if parent is not None and (not isinstance(parent, str) or not parent):
            raise ValueError("parent must be null or a nonempty string")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a nonnegative integer")
        if not isinstance(node["removable"], bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("utility must be finite")
        by_id[node_id] = node

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1 or roots[0]["depth"] != 0:
        raise ValueError("tree must have exactly one depth-zero root")
    root_id = roots[0]["id"]

    children = {node_id: [] for node_id in by_id}
    for node_id, node in by_id.items():
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            raise ValueError("parent does not exist")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("depth is inconsistent with parent")
        children[parent].append(node_id)

    visited = set()
    active = set()

    def visit(node_id):
        if node_id in active:
            raise ValueError("tree contains a cycle")
        if node_id in visited:
            return
        active.add(node_id)
        for child_id in children[node_id]:
            visit(child_id)
        active.remove(node_id)
        visited.add(node_id)

    visit(root_id)
    if len(visited) != len(by_id):
        raise ValueError("all nodes must belong to the root tree")
    if any(symbol not in {node["symbol"] for node in nodes} for symbol in required):
        raise ValueError("required symbol is not represented")

    retained = set(by_id)
    removal_order = []
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))
    for node in candidates:
        node_id = node["id"]
        if node_id == root_id or not node["removable"] or node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        remaining_symbols = {by_id[item]["symbol"] for item in retained if item != node_id}
        if not required.issubset(remaining_symbols):
            continue
        retained.remove(node_id)
        removal_order.append(node_id)

    return {
        "retained_ids": sorted(retained),
        "removal_order": removal_order,
    }
"}
